"""BC/CD public intermediate snapshots generated by C and consumed by D."""

import json
from pathlib import Path

import pytest

from aitest.application.execution.facts import ExecutionFactsAssembler, validate_execution_facts
from aitest.application.review.execution_decision_adapter import build_decision_facts
from aitest.contracts.execution_facts import ExecutionFacts
from aitest.domain.review.reports import BusinessOutcome, evaluate_review
from scripts.generate_cd001_fixtures import HALFWAY_NAMES, _build

PUBLIC = Path("docs/接口对接/已完成/CD-001-ExecutionFacts/fixtures")
CONSUMER = Path("tests/contracts/fixtures/execution_facts")


def load(name):
    return ExecutionFacts.model_validate_json((PUBLIC / f"{name}.json").read_bytes())


@pytest.mark.parametrize("name", [
    "success", "failure", "unknown", "quick", "timeout", "multistream",
    "non_utf8", "business_failure",
])
def test_existing_public_fixtures_can_still_be_regenerated(name):
    generated = ExecutionFactsAssembler().assemble(_build(name))
    assert generated.model_dump(mode="json", exclude_none=True) == json.loads(
        (PUBLIC / f"{name}.json").read_text(encoding="utf-8"),
    )


@pytest.mark.parametrize("name", HALFWAY_NAMES)
def test_generated_halfway_facts_have_identical_consumer_copy_and_no_passed_result(name):
    payload = json.loads((PUBLIC / f"{name}.json").read_text(encoding="utf-8"))
    generated = ExecutionFactsAssembler().assemble(_build(name))
    assert generated.model_dump(mode="json", exclude_none=True) == payload
    assert (PUBLIC / f"{name}.json").read_bytes() == (CONSUMER / f"{name}.json").read_bytes()
    validate_execution_facts(generated)
    assert generated.run.evidence_level is None
    assert generated.completeness.value == "partial"
    assert generated.run.ended_at is None
    decision = build_decision_facts(generated)
    assert decision.coverage.executed == frozenset()
    assert decision.coverage.verified == frozenset()
    assert evaluate_review(decision).business_outcome is BusinessOutcome.INCOMPLETE


def test_pause_requested_and_boundary_paused_preserve_history_and_scope():
    running, requested, paused = (load(name) for name in HALFWAY_NAMES[:3])
    assert running.run_id == requested.run_id == paused.run_id
    assert running.snapshot_cursor < requested.snapshot_cursor < paused.snapshot_cursor
    for facts in (running, requested):
        active = [step for step in facts.steps if step.state.value == "running"]
        assert len(active) == 1 and active[0].step_id == "step-2"
        assert facts.current_attempt_by_step["step-2"] == "attempt-2"
    assert requested.run.control_state.value == "pause_requested"
    assert paused.run.control_state.value == "paused"
    assert all(step.state.value != "running" for step in paused.steps)
    assert paused.steps[2].state.value == "ready"
    for facts in (requested, paused):
        assert facts.steps[0] == running.steps[0]
        assert facts.attempts[0] == running.attempts[0]
        assert facts.evidence_refs == running.evidence_refs
        assert facts.run.required_scope == running.run.required_scope
        assert facts.run.selected_scope == running.run.selected_scope
        assert facts.run.conclusion_ceiling == running.run.conclusion_ceiling


def test_revision_invalidates_basis_without_erasing_history_or_completed_step():
    before, after = load("paused"), load("revision_invalidated")
    assert after.snapshot_cursor > before.snapshot_cursor
    assert after.steps[0] == before.steps[0]
    assert after.attempts[0] == before.attempts[0]
    assert after.evidence_refs == before.evidence_refs
    assert after.steps[1].state.value == "invalidated"
    assert after.steps[1].invalidated_by == after.runtime_revision_refs[0]
    assert after.current_attempt_by_step["step-2"] == "attempt-2"
    assert after.attempts[1].exit_fact == before.attempts[1].exit_fact
    assert after.steps[2].step_revision_ref != before.steps[2].step_revision_ref
    assert after.run.required_scope == before.run.required_scope
    assert after.run.selected_scope == before.run.selected_scope
